import { Audio } from "@remotion/media";
import { staticFile } from "remotion";
import { TL } from "../theme";

/*
 * All sound for the intro. Music and most effects are generated by scripts/make_intro_audio.py;
 * mouse-click.wav is from remotion.media. Every cue is placed from src/timeline.json.
 * To change a sound: edit the script (or swap the file) and keep the same name.
 */
const E = TL.events;
const WHOOSH_PEAK = 12; // whoosh-soft.wav is loudest 0.4 s in; centre it on the transition

export const IntroAudio: React.FC = () => (
  <>
    <Audio name="Music bed" src={staticFile("audio/intro-bed.wav")} volume={0.62} />

    {E.cityPins.map((f, i) => (
      <Audio key={`pin${i}`} name={`City pin ${i + 1}`} from={f} src={staticFile("sfx/pop.wav")} volume={0.32} />
    ))}
    {E.whoosh.map((f, i) => (
      <Audio key={`wh${i}`} name={`Whoosh ${i + 1}`} from={f + TL.transitionFrames / 2 - WHOOSH_PEAK} src={staticFile("sfx/whoosh-soft.wav")} volume={0.55} />
    ))}
    {E.tiles.map((f, i) => (
      <Audio key={`tile${i}`} name={`Tile ${i + 1}`} from={f} src={staticFile("sfx/pop.wav")} volume={0.26} />
    ))}
    <Audio name="Click" from={E.click - 1} src={staticFile("sfx/mouse-click.wav")} volume={0.8} />
    <Audio name="Pin drop" from={E.pinDrop + 3} src={staticFile("sfx/pin-drop.wav")} volume={0.7} />
    {E.statuses.map((f, i) => (
      <Audio key={`st${i}`} name={`Status ${i + 1}`} from={f} src={staticFile(`sfx/status-${i + 1}.wav`)} volume={0.4} />
    ))}
    <Audio name="Dot chime" from={E.dot} src={staticFile("sfx/dot-chime.wav")} volume={0.45} />
    <Audio name="Logo impact" from={E.impact} src={staticFile("sfx/logo-impact.wav")} volume={0.85} />
  </>
);
